package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	TenantID string   `json:"tenant_id"`
	Limit    int      `json:"limit"`
}

type SearchResult struct {
	ID    int               `json:"id"`
	Data  map[string]string `json:"data"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

func sanitizeTenantID(tid string) string {
	// Basic alphanumeric check for tenant isolation
	for _, c := range tid {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-') {
			return "default"
		}
	}
	return tid
}

func buildSearchQuery(req SearchRequest) string {
	tid := sanitizeTenantID(req.TenantID)

	// Build field list - VULNERABILITY: fields are not sanitized
	fieldList := "id"
	if len(req.Fields) > 0 {
		fieldList = strings.Join(req.Fields, ", ")
	}

	limit := req.Limit
	if limit <= 0 || limit > 100 {
		limit = 20
	}

	// The query parameter uses parameterized query but fields are injected directly
	query := fmt.Sprintf(
		"SELECT %s FROM tenant_%s.documents WHERE content ILIKE '%%' || $1 || '%%' LIMIT %d",
		fieldList, tid, limit,
	)
	return query
}

func handleSearch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	if req.Query == "" {
		http.Error(w, "Query parameter required", 400)
		return
	}

	queryStr := buildSearchQuery(req)
	log.Printf("Executing search: %s with param: %s", queryStr, req.Query)

	rows, err := db.Query(queryStr, req.Query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	cols, _ := rows.Columns()
	var results []SearchResult
	for rows.Next() {
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		data := make(map[string]string)
		for i, col := range cols {
			if vals[i] != nil {
				data[col] = fmt.Sprintf("%v", vals[i])
			}
		}
		results = append(results, SearchResult{Data: data})
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", handleSearch)
	http.HandleFunc("/health", handleHealth)
	log.Printf("Starting document search service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
